scenarios.example_code:
import { capturePhoto } from '@projexlight/hdk-camera';
const result = await capturePhoto({ device: 'rear', format: 'jpeg' });
import { registerCapture } from '@projexlight/sdk-evidence';
await registerCapture({
  tenant_id, captured_by_persona_id, encounter_id,
  media_blob_id: result.blob.id,
  mime: 'image/jpeg',
  source_hash_sha256: result.source_hash,
  geo: result.exif.geo,
  device_attestation_signature: result.attestation_signature,
});

import { capturePhoto } from '@projexlight/hdk-camera';
const photo = await capturePhoto({ device: 'rear', format: 'heic', preset: 'medical-high' });
// → hand to sdk-evidence via registerCapture with PHI tenant-key tier

import { captureBurst } from '@projexlight/hdk-camera';
const frames = await captureBurst({ count: 5, interval_ms: 1000 });
for (const f of frames) await registerCapture({ ...f });

import { probeAttestation, capturePhoto } from '@projexlight/hdk-camera';
const trusted = await probeAttestation();
if (!trusted) {
  // show "this device cannot capture evidence; use a managed device"
  return;
}
const photo = await capturePhoto({ device: 'rear' });

// Tenant policy: hdk-camera/recording-presets returns:
// [{ id: 'default', resolution: '720p', max_seconds: 30 }]
const video = await captureVideo({ preset: 'default' });
// Recording stops automatically at 30s.
